changeSet.sql:
UPDATE UNIPOST_WORKSPACES w
SET tenant_ref_id = t.id
FROM UNIPOST_TENANTS t
WHERE w.tenant_id = t.code;

-- Create partial index on active tenants
CREATE INDEX IF NOT EXISTS idx_tenants_code_active 
ON UNIPOST_TENANTS (code) 
WHERE "deletedDate" IS NULL;

-- Enable and Force Row-Level Security on UNIPOST_TENANTS
ALTER TABLE UNIPOST_TENANTS ENABLE ROW LEVEL SECURITY;
ALTER TABLE UNIPOST_TENANTS FORCE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS tenant_isolation_tenants ON UNIPOST_TENANTS;
CREATE POLICY tenant_isolation_tenants ON UNIPOST_TENANTS
    FOR ALL
    USING (
        current_setting('app.current_tenant_id', true) = 'SYSTEM'
        OR code = NULLIF(current_setting('app.current_tenant_id', true), '')
    )
    WITH CHECK (
        current_setting('app.current_tenant_id', true) = 'SYSTEM'
        OR (
            code = NULLIF(current_setting('app.current_tenant_id', true), '')
            AND code != 'SYSTEM'
        )
    );
